import sys
import os
import shutil

if hasattr(sys.stdout, 'reconfigure'):
    sys.stdout.reconfigure(encoding='utf-8')
if hasattr(sys.stderr, 'reconfigure'):
    sys.stderr.reconfigure(encoding='utf-8')

SCRATCH = r"C:\Users\lorik\.gemini\antigravity\scratch"

def safe_move(src, dst):
    if not os.path.exists(src):
        return
    if os.path.exists(dst):
        if os.path.isdir(dst):
            shutil.rmtree(dst)
        else:
            os.remove(dst)
    shutil.move(src, dst)
    print(f"  -> Moved {os.path.basename(src)} to {dst}")

def finish_organization():
    print("[+] Finishing organization of packs and mbb items...")
    unknown_dir = os.path.join(SCRATCH, "unknown")
    anymd_packs_dir = os.path.join(SCRATCH, "anymd_suite", "packs")
    mbb_suite_dir = os.path.join(SCRATCH, "mbb_suite")

    os.makedirs(anymd_packs_dir, exist_ok=True)
    os.makedirs(mbb_suite_dir, exist_ok=True)

    if os.path.exists(unknown_dir):
        for item in os.listdir(unknown_dir):
            src = os.path.join(unknown_dir, item)
            if item.startswith("anymd-"):
                dst = os.path.join(anymd_packs_dir, item)
                safe_move(src, dst)
            elif item.startswith("mbb-"):
                dst = os.path.join(mbb_suite_dir, item)
                safe_move(src, dst)
        try:
            if not os.listdir(unknown_dir):
                os.rmdir(unknown_dir)
                print("  -> Removed empty unknown directory.")
        except Exception as e:
            print(f"  -> Notice: {e}")

    print("[SUCCESS] Directory structure organized cleanly!")

if __name__ == "__main__":
    finish_organization()
